using System;
using System.Drawing;
using System.Linq;
using System.Windows.Forms;
namespace LoopPedal {
partial class Pedal {
 Layer menuLayer;Engine menuEngine;ContextMenuStrip currentPopup;
 StudioNumber tempoSetting;StudioChoice meterSetting,countSetting;PadButton audioMenuPad,fxMenuPad;
 ContextMenuStrip NewMenu(){if(currentPopup!=null)currentPopup.Dispose();menuLayer=null;menuEngine=null;return currentPopup=new ContextMenuStrip{Renderer=new StudioMenuRenderer(),ShowImageMargin=false,BackColor=Skin.Panel,ForeColor=Color.WhiteSmoke,Font=Font};}
 ToolStripMenuItem Item(ToolStripItemCollection target,string text,Action action=null,bool check=false){var item=new ToolStripMenuItem(text){Checked=check};var guardedLayer=menuLayer;var guardedEngine=menuEngine;if(action!=null)item.Click+=(s,e)=>{try{if(guardedLayer!=null){lock(guardedEngine.Gate)if(!guardedEngine.Layers.Contains(guardedLayer)){status.Text="Layer changed. Reopen its menu.";return;}}action();}catch(Exception ex){status.Text=ex.Message;}};target.Add(item);return item;}
 void NumberMenu(string title,decimal value,decimal min,decimal max,int places,Action<decimal> set){using(var form=new Form{Text=title,Size=new Size(260,140),FormBorderStyle=FormBorderStyle.FixedToolWindow,StartPosition=FormStartPosition.CenterParent,BackColor=Skin.Ink,ForeColor=Color.WhiteSmoke,ShowInTaskbar=false}){var number=new StudioNumber{Location=new Point(18,16),Width=205,Minimum=min,Maximum=max,DecimalPlaces=places,Value=Math.Max(min,Math.Min(max,value)),BackColor=Skin.Panel,ForeColor=Color.WhiteSmoke};form.Controls.Add(number);var ok=new PadButton{Text="SET",Location=new Point(128,58),Size=new Size(95,32),DialogResult=DialogResult.OK};form.Controls.Add(ok);form.AcceptButton=ok;if(form.ShowDialog(this)==DialogResult.OK){form.ActiveControl=ok;set(number.Value);}}}
 void TimingItems(ToolStripItemCollection items){Item(items,"Tempo · "+loopers[0].BPM.ToString("0.#")+" BPM",()=>NumberMenu("Tempo",tempoSetting.Value,20,300,1,v=>tempoSetting.Value=v));var meter=Item(items,"Time signature");for(int i=0;i<meterSetting.Items.Count;i++){int n=i;Item(meter.DropDownItems,meterSetting.Items[i].ToString(),()=>meterSetting.SelectedIndex=n,meterSetting.SelectedIndex==i);}var count=Item(items,"Count-in");for(int i=0;i<3;i++){int n=i;Item(count.DropDownItems,i==0?"Off":i+" measure"+(i==1?"":"s"),()=>countSetting.SelectedIndex=n,countSetting.SelectedIndex==i);}Item(items,"Recording click",()=>{bool enabled=!loopers[0].ClickDuringRecord;foreach(var b in loopers)b.ClickDuringRecord=enabled;},loopers[0].ClickDuringRecord);}
 void ShowTimingMenu(Control anchor){var menu=NewMenu();TimingItems(menu.Items);menu.Show(anchor,0,anchor.Height);}
 void ShowMainMenu(Control anchor){var menu=NewMenu();var files=Item(menu.Items,"Files · "+(activeBank==0?"A":"B"));Item(files.DropDownItems,"Import audio / video…",Import);Item(files.DropDownItems,"Export WAV",Export);var timing=Item(menu.Items,"Timing");TimingItems(timing.DropDownItems);var layout=Item(menu.Items,"Layout");var fullscreen=Item(layout.DropDownItems,immersive?"Exit fullscreen":"Immersive fullscreen",()=>SetImmersive(!immersive),immersive);fullscreen.ShortcutKeyDisplayString="F11";Item(layout.DropDownItems,"Single looper",()=>SetSingleMode(true),singleMode);Item(layout.DropDownItems,"Dual loopers",()=>SetSingleMode(false),!singleMode);Item(menu.Items,"Audio devices",()=>audioMenuPad.PerformClick());Item(menu.Items,"MIDI",ShowMidi);var fx=Item(menu.Items,"Master FX");Item(fx.DropDownItems,"Show / hide panel",()=>fxMenuPad.PerformClick());Item(fx.DropDownItems,"Reset tails",()=>loopers[0].Fx.Clear());menu.Show(anchor,0,anchor.Height);}
 void ShowBankMenu(int bank,Control anchor){SelectBank(bank);var b=loopers[bank];var menu=NewMenu();var record=Item(menu.Items,"Recording");var mode=Item(record.DropDownItems,"Mode");Item(mode.DropDownItems,"Layers",()=>{if(b.Destructive)SetDestructiveUi(bank);},!b.Destructive);Item(mode.DropDownItems,"Destructive",()=>{if(!b.Destructive)SetDestructiveUi(bank);},b.Destructive);Item(record.DropDownItems,"Auto overdub",()=>b.SetAutoOverdub(!b.AutoOverdub),b.AutoOverdub);Item(record.DropDownItems,"Wait for input",()=>b.WaitForInput=!b.WaitForInput,b.WaitForInput);Item(record.DropDownItems,"Trigger · "+b.TriggerDb.ToString("0")+" dBFS",()=>NumberMenu("Input trigger dBFS",(decimal)b.TriggerDb,-72,-6,0,v=>b.TriggerDb=(double)v));var sync=Item(menu.Items,b.Destructive?"Sync":"Sync / Warp");var length=Item(sync.DropDownItems,"Length");Item(length.DropDownItems,"Free",()=>b.Sync=false,!b.Sync);foreach(int bars in new[]{1,2,4,8,16,32,64}){int n=bars;Item(length.DropDownItems,n+" measure"+(n==1?"":"s"),()=>{b.Sync=true;b.Bars=n;},b.Sync&&b.Bars==n);}var start=Item(sync.DropDownItems,"Start");string[] starts={"Now","Measure",bank==0?"B loop":"A loop"};for(int i=0;i<3;i++){int n=i;Item(start.DropDownItems,starts[i],()=>{if(b.Recording)b.Finish(false);b.PlaybackPending=false;b.StartQuantize=n;},b.StartQuantize==i);}if(!b.Destructive)Item(sync.DropDownItems,b.WarpPending?"Warp · armed":"Warp layers",()=>ToggleWarp(bank),b.WarpLayers||b.WarpPending);var input=Item(menu.Items,"Input");if(bank==1){for(int i=0;i<3;i++){int n=i;Item(input.DropDownItems,new[]{"Live","Looper A","Live + A"}[i],()=>{if(b.Recording)b.Finish(false);b.InputMode=n;},b.InputMode==i);}}Item(input.DropDownItems,"Audio devices",()=>audioMenuPad.PerformClick());var history=Item(menu.Items,"History");Item(history.DropDownItems,"Undo · "+b.UndoCount,()=>RestoreHistory(bank,false));Item(history.DropDownItems,"Redo · "+b.RedoCount,()=>RestoreHistory(bank,true));Item(history.DropDownItems,"Clear looper",()=>{b.ClearLoop();RefreshTracks();});menu.Show(anchor,0,anchor.Height);}
 void ShowLayerMenu(Engine b,Layer t,Control anchor){var menu=NewMenu();menuLayer=t;menuEngine=b;var playback=Item(menu.Items,"Playback");Item(playback.DropDownItems,"Mute",()=>{t.Mute=!t.Mute;RefreshTracks();},t.Mute);Item(playback.DropDownItems,"Solo",()=>{t.Solo=!t.Solo;RefreshTracks();},t.Solo);Item(playback.DropDownItems,"Reverse",()=>{t.Reverse=!t.Reverse;Process(t);},t.Reverse);var algorithm=Item(playback.DropDownItems,"Pitch / stretch");for(int i=0;i<4;i++){int n=i;Item(algorithm.DropDownItems,new[]{"R3 Live · Music","R3 Live · Formants","R3 Render · Music","R3 Render · Formants"}[i],()=>{t.LiveMode=n<2;t.PreserveFormants=n%2==1;Process(t);RefreshTracks();},(t.LiveMode?0:2)+(t.PreserveFormants?1:0)==i);}var region=Item(menu.Items,"Region");double duration=t.Original.Length/(2.0*DSP.Rate);Item(region.DropDownItems,"Start…",()=>NumberMenu("Start (seconds)",(decimal)(t.TrimStart*duration),0,(decimal)Math.Max(0,duration-.001),3,v=>{t.TrimStart=(double)v/duration;Process(t);}));Item(region.DropDownItems,"Length…",()=>NumberMenu("Length (seconds)",(decimal)(t.TrimLength*duration*t.Stretch),.001m,(decimal)Math.Max(300,duration*t.Stretch),3,v=>{t.TrimLength=(double)v/(duration*t.Stretch);Process(t);}));Item(region.DropDownItems,"Half length",()=>{t.TrimLength=Math.Max(.001/duration,t.TrimLength/2);Process(t);});Item(region.DropDownItems,"Double length",()=>{t.TrimLength=Math.Min(2,t.TrimLength*2);Process(t);});Item(region.DropDownItems,"Full take",()=>{t.TrimStart=0;t.TrimLength=1;Process(t);});Item(menu.Items,"Delete layer",()=>{b.DeleteLayer(t);RefreshTracks();});menu.Show(anchor,0,anchor.Height);}
 void DispatchMidiAction(string action){string[] parts=action.Split('.');if(parts.Length!=2)return;int bank=parts[0]=="B"?1:0;BankAction(bank,()=>{var b=loopers[bank];switch(parts[1]){case "Record":Record(false);break;case "Overdub":Record(true);break;case "PlayStop":if(b.Recording)b.Finish(false);b.TogglePlayback();RefreshTracks(true);break;case "Undo":RestoreHistory(bank,false);break;case "Redo":RestoreHistory(bank,true);break;case "Clear":b.ClearLoop();RefreshTracks();break;case "AutoOverdub":b.SetAutoOverdub(!b.AutoOverdub);break;}});}
}
}
